import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int P = Integer.parseInt(st.nextToken());

        int[] rows = new int[N + 1];
        int[] cols = new int[M + 1];

        for (int i = 1; i <= N; i++) rows[i] = i;
        for (int j = 1; j <= M; j++) cols[j] = j;

        for (int p = 0; p < P; p++) {
            st = new StringTokenizer(br.readLine());
            char op = st.nextToken().charAt(0);
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());

            if (op == 'L') {
                int tmp = rows[a];
                rows[a] = rows[b];
                rows[b] = tmp;
            } else {
                int tmp = cols[a];
                cols[a] = cols[b];
                cols[b] = tmp;
            }
        }

        FastOutput out = new FastOutput(System.out);

        for (int i = 1; i <= N; i++) {
            int base = (rows[i] - 1) * M;
            for (int j = 1; j <= M; j++) {
                out.writeInt(base + cols[j]);
                if (j < M) out.writeByte(' ');
            }
            out.writeByte('\n');
        }

        out.flush();
    }

    static class FastOutput {
        private final OutputStream os;
        private final byte[] buf = new byte[1 << 16];
        private int idx = 0;

        FastOutput(OutputStream os) {
            this.os = os;
        }

        private void flushBuffer() throws IOException {
            if (idx > 0) {
                os.write(buf, 0, idx);
                idx = 0;
            }
        }

        void writeInt(int x) throws IOException {
            if (x == 0) {
                writeByte('0');
                return;
            }

            if (x < 0) {
                writeByte('-');
                x = -x;
            }

            if (idx + 12 >= buf.length) flushBuffer();

            int pos = idx + 11;
            int end = pos;

            while (x > 0) {
                buf[pos--] = (byte) ('0' + (x % 10));
                x /= 10;
            }

            int start = pos + 1;
            int len = end - start + 1;
            System.arraycopy(buf, start, buf, idx, len);
            idx += len;
        }

        void writeByte(int c) throws IOException {
            if (idx == buf.length) flushBuffer();
            buf[idx++] = (byte) c;
        }

        void flush() throws IOException {
            flushBuffer();
            os.flush();
        }
    }
}
